import{_ as r,o as e,c as a,ag as d}from"./chunks/framework.Aev9KvMf.js";const i=JSON.parse('{"title":"标签要变什么 · GB 7718-2025 新旧对比（2027 实施预告）","description":"GB 7718 新旧对比预告：生产日期+保质期到期日双标示、八大类致敏物质强制提示、数字标签规范、消费保存期，逐条链接官方问答。","frontmatter":{"title":"标签要变什么 · GB 7718-2025 新旧对比（2027 实施预告）","issuer":"国家卫生健康委（标准问答）","source_tier":"一级来源","version":"GB 7718—2011 → GB 7718—2025","published":"2025-09","source_url":"https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml","status":"新版已发布（2027-03-16 实施）","tags":["国标","食品标签","新版对比","致敏物质","行动清单"],"type":"国标科普","reviewed":false,"description":"GB 7718 新旧对比预告：生产日期+保质期到期日双标示、八大类致敏物质强制提示、数字标签规范、消费保存期，逐条链接官方问答。"},"headers":[],"relativePath":"standards/gb7718-2025-preview.md","filePath":"standards/gb7718-2025-preview.md"}'),s={name:"standards/gb7718-2025-preview.md"};function o(c,t,n,l,h,b){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="标签要变什么-·-gb-7718-2025-新旧对比-2027-实施预告" tabindex="-1">标签要变什么 · GB 7718-2025 新旧对比（2027 实施预告） <a class="header-anchor" href="#标签要变什么-·-gb-7718-2025-新旧对比-2027-实施预告" aria-label="Permalink to &quot;标签要变什么 · GB 7718-2025 新旧对比（2027 实施预告）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据国家卫健委官方问答整理，尚未逐条对照原文校验；校验通过前请以官方问答与标准原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家卫健委官方问答</strong>（一级来源），逐条可点击溯源。本站不构成诊疗建议。</p></div><blockquote><p><strong>出处</strong>：《食品安全国家标准 预包装食品标签通则》（GB 7718-2025）问答，国家卫生健康委（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">官方问答页</a>）。<strong>2027 年 3 月 16 日实施</strong>，与 GB 28050-2025 同批。</p></blockquote><h2 id="速览卡-给家庭的四个变化" tabindex="-1">速览卡（给家庭的四个变化） <a class="header-anchor" href="#速览卡-给家庭的四个变化" aria-label="Permalink to &quot;速览卡（给家庭的四个变化）&quot;">​</a></h2><ol><li><strong>日期双标示</strong>：生产日期和<strong>保质期到期日</strong>必须同时标示——以后不用自己算&quot;还有几天到期&quot;。</li><li><strong>八大类致敏物质强制提示</strong>：含麸质谷物、甲壳纲（虾蟹）、鱼、蛋、花生、大豆、乳、坚果直接入配料时，须加粗/下划线或在配料表旁提示——<strong>过敏孩子的家长重点看这条</strong>。</li><li><strong>数字标签来了</strong>：鼓励扫码看完整标签信息（可放大、可语音），不得弹窗干扰、修改需可追溯。</li><li><strong>&quot;消费保存期&quot;可自愿标示</strong>：超过保质期但可能仍可食用的参考日期（不短于保质期；超过保质期的食品仍不得销售）。</li></ol><h2 id="新旧对比表" tabindex="-1">新旧对比表 <a class="header-anchor" href="#新旧对比表" aria-label="Permalink to &quot;新旧对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>现行 GB 7718—2011</th><th>新版 GB 7718—2025</th><th>出处</th></tr></thead><tbody><tr><td>日期标示</td><td>生产日期 + 保质期</td><td><strong>生产日期 + 保质期到期日</strong>同时标示（到期日从生产日当日/次日起算）；标示两日期后&quot;保质期&quot;可自愿标示</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·日期标示</a></td></tr><tr><td>致敏物质</td><td>推荐标示</td><td><strong>八大类直接作配料时强制提示</strong>（加粗/下划线/临近提示）；交叉污染鼓励&quot;可能含有&quot;提示；芝麻、椰子等自愿</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·致敏物质</a></td></tr><tr><td>数字标签</td><td>无</td><td>鼓励使用：内容须符合强制标示规定、不得篡改、修改可追溯、<strong>不得有弹窗飘窗干扰</strong>；鼓励音频视频与多码合一</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·数字标签</a></td></tr><tr><td>消费保存期</td><td>无</td><td>可自愿标示为&quot;最后食用日期&quot;参考（不应短于保质期）</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·日期标示</a></td></tr><tr><td>豁免</td><td>有</td><td>两种豁免情形保留（特定食品种类/包装 ≤20cm²）；葡萄酒及 ≥10%vol 酒类标批号可免日期；普洱茶、黑茶可标&quot;长期保存&quot;</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·豁免</a></td></tr></tbody></table><h2 id="给家庭的行动清单" tabindex="-1">给家庭的行动清单 <a class="header-anchor" href="#给家庭的行动清单" aria-label="Permalink to &quot;给家庭的行动清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>现在买食品：教家人看配料表递减排序 + 生产日期保质期（2011 版现行）</td><td><a href="/SageRelay/standards/gb7718-food-label.html">GB 7718 词条</a></td></tr><tr><td>有过敏孩子的家庭：2027 年后致敏物质在配料表里<strong>加粗或下划线</strong>，一眼可见</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·致敏物质</a></td></tr><tr><td>老人买菜：以后直接读&quot;保质期到期日&quot;，不用按保质期倒推</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·日期标示</a></td></tr><tr><td>【本站提示】扫码出现弹窗广告的&quot;数字标签&quot;不符合新规要求——新规明确禁止弹窗飘窗干扰</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·数字标签</a></td></tr></tbody></table><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>版本</td><td>GB 7718—2011（现行）→ GB 7718—2025（2027-03-16 实施）</td></tr><tr><td>归口</td><td>国家卫生健康委（食品安全国家标准）</td></tr><tr><td>出处</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">官方问答页</a> · <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准查询（全文公开系统）</a></td></tr></tbody></table>',12)])])}const p=r(s,[["render",o]]);export{i as __pageData,p as default};
